106	function markdownToHtml(md) {
107	  let html = md;
108	
109	  // Code blocks
110	  html = html.replace(/```([a-z]*)\n([\s\S]*?)```/g, (m, lang, code) => {
111	    code = code.trim().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
112	    return `<pre><code class="language-${lang}">${code}</code></pre>`;
113	  });
114	
115	  // Inline code
116	  html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');
117	
118	  // Bold, italic, links
119	  html = html.replace(/\*\*([^\*\n]+)\*\*/g, '<strong>$1</strong>');
120	  html = html.replace(/\*([^\*\n]+)\*/g, '<em>$1</em>');
121	  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
122	
123	  // Headings
124	  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
125	  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
126	  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
127	
