      background: #f9f9f9;
      padding: 20px;
      border-radius: 8px;
      margin-bottom: 30px;
    }
    .form-group {
      margin-bottom: 15px;
    }
    .form-group label {
      display: block;
      margin-bottom: 5px;
      font-weight: 600;
      color: #333;
    }
    .form-group input, .form-group textarea {
      width: 100%;
      padding: 10px;
      border: 1px solid #ddd;
      border-radius: 4px;
      font-family: Arial, sans-serif;
    }
    .form-group textarea {
      resize: vertical;
      min-height: 100px;
    }
    .form-group button {
      background: #667eea;
      color: white;
      border: none;
      padding: 10px 20px;
      border-radius: 4px;
      cursor: pointer;
      font-weight: 600;
    }
    .form-group button:hover {
      background: #5568d3;
    }
    .comments-list { margin-top: 30px; }
    .comment {
      border-left: 3px solid #667eea;
      padding: 15px;
      margin: 15px 0;
      background: #f9f9f9;
    }
    .comment-author { font-weight: 600; }
    .comment-date { color: #999; font-size: 0.9em; }
    .comment-text { margin: 10px 0; line-height: 1.6; }
    .comment-actions { font-size: 0.9em; }
    .comment-actions a { color: #ff6b6b; cursor: pointer; }
    .nav { margin-top: 40px; }
    .nav a { color: #667eea; text-decoration: none; }
  </style>
</head>
<body>
  <div class="container">
    <div class="post-header">
      <div class="post-date">${new Date(post.date).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}</div>
      <h1 class="post-title">${post.title}</h1>
    </div>

    <div class="post-content">
      ${contentHtml}
    </div>

    <div class="comments-section">
      <h2 class="comments-title">💬 댓글 (${postComments.length})</h2>

      <div class="comment-form">
        <h3 style="margin-bottom: 15px;">댓글 작성</h3>
        <div class="form-group">
          <label>이름</label>
          <input type="text" id="author" placeholder="이름" maxlength="50">
        </div>
        <div class="form-group">
